class Value {
    int v;
public:
    Value(int val) : v(val) {}

    // Binary arithmetic (Member)
    Value operator+(const Value& other) const {
        return Value(v + other.v);
    }

    // Unary prefix (Member)
    Value& operator++() {
        ++v;
        return *this;
    }

    // Stream output (Non-member friend declaration)
    friend std::ostream& operator<<(std::ostream& os, const Value& obj);
};

// Example Non-Member Implementation
std::ostream& operator<<(std::ostream& os, const Value& obj) {
    return os << "Val: " << obj.v;
}
